import "server-only";

import fs from "node:fs";
import path from "node:path";

import type { DosageForm } from "@/lib/types";

import { normalizeDrugKey } from "./normalize";
import type { CatalogDrug, CatalogMeta, DrugSuggestion } from "./types";

/**
 * Local (no-Supabase) implementation of the official drug catalogue.
 *
 * The dataset is generated by `extract_drugs.py` from the TITAN `egypt.phar.phy`
 * flat file and written to `src/data/drugs-catalog.json`. It is read from disk
 * (never imported) so ~18k rows stay out of the client bundle, then indexed in
 * memory once per server process.
 *
 * Rows are indexed by BOTH the Arabic and the English trade name, because
 * pharmacists search in Arabic (`كونكور`) while many packages only carry the
 * Latin brand (`CONCOR`) — the extractor often has both, sometimes only one.
 */

interface RuntimeRow {
  id: string;
  n: string; // name_en
  a: string; // name_ar
  i: string; // active ingredient
  c: string; // company
  f: DosageForm;
  p: number; // public price
  k: number | null; // pack size
  g: string; // category
}

interface RuntimeFile {
  meta: CatalogMeta;
  drugs: RuntimeRow[];
}

interface IndexedDrug {
  drug: CatalogDrug;
  /** Distinct normalised name keys — Arabic first when present. */
  keys: string[];
  tokenKeys: string[][];
  ingredientKey: string;
  companyKey: string;
}

interface CatalogIndex {
  entries: IndexedDrug[];
  meta: CatalogMeta;
}

const CATALOG_PATH = path.join(process.cwd(), "src", "data", "drugs-catalog.json");

let index: CatalogIndex | null = null;
let loadFailed = false;

function splitKey(key: string): string[] {
  return key ? key.split(" ") : [];
}

function build(): CatalogIndex {
  const raw = fs.readFileSync(CATALOG_PATH, "utf8");
  const parsed = JSON.parse(raw) as RuntimeFile;

  const entries: IndexedDrug[] = parsed.drugs.map((row) => {
    const arabicKey = normalizeDrugKey(row.a);
    const latinKey = normalizeDrugKey(row.n);
    const keys = [arabicKey, latinKey].filter((key, position, all) => key && all.indexOf(key) === position);

    return {
      drug: {
        id: row.id,
        name_en: row.n,
        name_ar: row.a,
        active_ingredient: row.i,
        company: row.c,
        dosage_form: row.f,
        pack_size: row.k ?? null,
        category: row.g ?? "",
        public_price_egp: Number(row.p) || 0,
        barcode: null,
      },
      keys,
      tokenKeys: keys.map(splitKey),
      ingredientKey: normalizeDrugKey(row.i),
      companyKey: normalizeDrugKey(row.c),
    };
  });

  return { entries, meta: parsed.meta };
}

function getIndex(): CatalogIndex | null {
  if (index) return index;
  if (loadFailed) return null;
  try {
    index = build();
    return index;
  } catch (error) {
    loadFailed = true;
    console.error("[drugs] catalogue unavailable — run `python extract_drugs.py`", error);
    return null;
  }
}

/** Best score for one name key: exact > prefix > word-prefix > substring. */
function scoreKey(key: string, tokens: string[], needle: string): number {
  if (!key) return 0;
  if (key === needle) return 100;

  if (key.startsWith(needle)) {
    // "concor 5" beats "concor cor 2.5": shorter remainder wins.
    return 88 - Math.min(12, (key.length - needle.length) / 6);
  }

  // A later word may still start with the needle ("advance panadol").
  for (const token of tokens) {
    if (token.startsWith(needle)) return 74;
  }

  const position = key.indexOf(needle);
  if (position > 0) return 56 - Math.min(16, position / 4);
  return 0;
}

function scoreEntry(entry: IndexedDrug, needle: string): number {
  let nameScore = 0;
  for (let i = 0; i < entry.keys.length; i += 1) {
    const score = scoreKey(entry.keys[i], entry.tokenKeys[i], needle);
    if (score > nameScore) nameScore = score;
  }

  if (nameScore > 0) {
    // Prefer rows that also carry the other language's name and an ingredient.
    return nameScore + (entry.drug.name_ar ? 2 : 0) + (entry.drug.active_ingredient ? 1 : 0);
  }

  if (entry.ingredientKey.includes(needle)) return 34;
  if (entry.companyKey.includes(needle)) return 18;
  return 0;
}

function primaryKeyLength(entry: IndexedDrug): number {
  return entry.keys[0]?.length ?? 0;
}

/** Character bigrams — cheap Dice coefficient for transliteration variants. */
function bigrams(value: string): Set<string> {
  const set = new Set<string>();
  for (let i = 0; i < value.length - 1; i += 1) set.add(value.slice(i, i + 2));
  return set;
}

function dice(a: Set<string>, b: Set<string>): number {
  if (a.size === 0 || b.size === 0) return 0;
  let shared = 0;
  for (const gram of a) if (b.has(gram)) shared += 1;
  return (2 * shared) / (a.size + b.size);
}

/**
 * Fallback for transliteration differences: pharmacists type `بانادول` while
 * the TITAN catalogue stores `بنادول`. Bigram similarity catches those without
 * any external dependency. Only runs when the exact/prefix pass found little.
 */
function fuzzyPass(entries: IndexedDrug[], needle: string, exclude: Set<string>) {
  const needleGrams = bigrams(needle);
  const hits: Array<{ entry: IndexedDrug; score: number }> = [];

  for (const entry of entries) {
    if (exclude.has(entry.drug.id)) continue;
    let best = 0;
    for (const key of entry.keys) {
      const similarity = dice(needleGrams, bigrams(key));
      if (similarity > best) best = similarity;
    }
    if (best >= 0.5) hits.push({ entry, score: 24 + best * 44 });
  }

  return hits;
}

export function searchLocalCatalog(query: string, limit = 8): DrugSuggestion[] {
  const needle = normalizeDrugKey(query);
  if (needle.length < 2) return [];

  const loaded = getIndex();
  if (!loaded) return [];

  const scored: Array<{ entry: IndexedDrug; score: number }> = [];
  for (const entry of loaded.entries) {
    const score = scoreEntry(entry, needle);
    if (score > 0) scored.push({ entry, score });
  }

  if (scored.length < 3) {
    const seen = new Set(scored.map((hit) => hit.entry.drug.id));
    scored.push(...fuzzyPass(loaded.entries, needle, seen));
  }

  scored.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    const lengthDiff = primaryKeyLength(a.entry) - primaryKeyLength(b.entry);
    if (lengthDiff !== 0) return lengthDiff;
    return a.entry.drug.public_price_egp - b.entry.drug.public_price_egp;
  });

  return scored.slice(0, limit).map(({ entry, score }) => ({
    ...entry.drug,
    score: Math.round(score * 10) / 10,
  }));
}

export function getCatalogDrug(id: string): CatalogDrug | null {
  const loaded = getIndex();
  if (!loaded) return null;
  const entry = loaded.entries.find((item) => item.drug.id === id);
  return entry ? entry.drug : null;
}

export function catalogMeta(): CatalogMeta | null {
  const loaded = getIndex();
  return loaded ? loaded.meta : null;
}

export function catalogSize(): number {
  const loaded = getIndex();
  return loaded ? loaded.entries.length : 0;
}
